namespace gui_forms {

// The enumerations several property families name, each made a property
// value once here; generated by tools/property_codemod.py from
// tools/property_families/shared.json ("enumerations"). Defined in
// src/controls/shared_property_enums/shared_property_enums.cpp.

template <>
struct PropertyValueTraits<ChoiceIndicatorStyle> {
    static PropertyType type();
    static BindingValue to_binding(ChoiceIndicatorStyle value);
    static ChoiceIndicatorStyle from_binding(const BindingValue& value);
};

template <>
struct PropertyValueTraits<HorizontalAlignment> {
    static PropertyType type();
    static BindingValue to_binding(HorizontalAlignment value);
    static HorizontalAlignment from_binding(const BindingValue& value);
};

template <>
struct PropertyValueTraits<ScaledAspect> {
    static PropertyType type();
    static BindingValue to_binding(ScaledAspect value);
    static ScaledAspect from_binding(const BindingValue& value);
};

} // namespace gui_forms
